<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Pato na Pista</title><script src="https://unpkg.com/vue@3/dist/vue.global.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><style>*{box-sizing:border-box}body{margin:0;background:#fffaf0;color:#10283d;font:16px system-ui}header{background:#10283d;color:#fff;padding:14px 5vw;font-weight:900;display:flex;justify-content:space-between}header a{color:#ffd45c;text-decoration:none}main{max-width:1450px;margin:auto;padding:24px}.hero{display:flex;justify-content:space-between;align-items:center}.hero h1{font-size:clamp(42px,6vw,76px);line-height:.95;letter-spacing:-.06em;margin:8px 0}.panel{background:#fff;border:2px solid #10283d;border-radius:20px;box-shadow:6px 6px #10283d;padding:20px;margin-top:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}.add{display:flex;gap:10px}.add input{flex:1;font:inherit;border:2px solid #dbe5e8;border-radius:12px;padding:13px}.duration{width:85px;padding:9px;border:2px solid #dbe5e8;border-radius:10px}button{border:2px solid #10283d;border-radius:999px;padding:12px 18px;background:#ffd45c;font-weight:900;cursor:pointer;margin:10px 8px 0 0}.secondary{background:#fff}.participants{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.pill{background:#d8f4f4;border-radius:999px;padding:7px 12px;cursor:pointer}.qr{display:flex;gap:18px;align-items:center}.qr canvas,.qr img{width:230px!important;height:230px!important;border:10px solid #fff}.fullscreen{position:fixed;inset:0;background:linear-gradient(#10283d,#16465c);color:#fff;z-index:50;overflow:auto;padding:clamp(14px,3vw,42px)}.race-top{display:flex;justify-content:space-between;align-items:center;gap:20px;max-width:1450px;margin:auto}.race-top h1{font-size:clamp(30px,5vw,70px);line-height:.9;margin:0;letter-spacing:-.06em}.timer{font-size:clamp(30px,5vw,70px);color:#ffd45c;font-weight:900}.track-card{max-width:1200px;margin:18px auto;background:#315c69;border:3px solid #5e9ca3;border-radius:22px;overflow:hidden}.track-svg{width:100%;height:auto;display:block}.dot-name{font:700 15px system-ui;fill:#10283d}.leaderboard{max-width:560px;margin:18px auto;background:#fff;color:#10283d;border-radius:18px;padding:15px}.leader{display:flex;gap:8px;padding:8px;border-bottom:1px solid #dce6e8}.rank{width:30px;font-weight:900}.swatch{width:13px;height:13px;border-radius:50%;margin-top:5px}.result{max-width:620px;margin:18px auto;background:#fff;color:#10283d;border-radius:18px;padding:18px;text-align:center}@media(max-width:760px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.hero{display:block}.add{flex-direction:column}}
</style></head><body><header><span>PATO NA PISTA 🦆</span><a href="/">← Voltar para home</a></header><main id="app"><div class="hero"><div><small>SALA @{{ race.code }}</small><h1>Prepare a corrida.</h1><p>@{{ race.names.length }} participantes · bolinhas visíveis e sem rotação.</p></div><div style="font-size:90px">●</div></div><section class="panel"><div class="grid"><div class="full"><label>Cadastre os participantes</label><div class="add"><input v-model="newName" @keyup.enter="addName" placeholder="Digite um nome"><button @click="addName">Cadastrar nome</button></div><div class="participants"><span v-for="name in race.names" class="pill" @click="removeName(name)">@{{ name }} ×</span></div></div><div><label>Duração <input class="duration" type="number" v-model.number="duration" min="5" max="300"> segundos</label><br><button @click="startRace">Começar corrida</button><button class="secondary" @click="openQr">QR em tela cheia</button></div><div class="qr"><div id="qrcode"></div><span>Escaneie para entrar<br>@{{ joinUrl }}</span></div></div></section><div v-if="raceScreen" class="fullscreen"><div class="race-top"><div><small>🏁 CIRCUITO AO VIVO · SALA @{{ race.code }}</small><h1>@{{ finished?'🏆 Temos um campeão!':'Quem vai ganhar?' }}</h1></div><div><div class="timer">@{{ finished?'FIM':Math.ceil(remaining)+'s' }}</div><button class="secondary" @click="raceScreen=false">Sair</button></div></div><div class="track-card"><svg class="track-svg" viewBox="0 0 1000 520"><path id="racePath" d="M180,260 C180,105 350,55 500,55 C650,55 820,105 820,260 C820,415 650,465 500,465 C350,465 180,415 180,260 Z" fill="none" stroke="#88d8d4" stroke-width="100" stroke-linecap="round"/><path d="M180,260 C180,105 350,55 500,55 C650,55 820,105 820,260 C820,415 650,465 500,465 C350,465 180,415 180,260 Z" fill="none" stroke="#5b9b82" stroke-width="86" stroke-linecap="round" stroke-dasharray="16 14"/><g v-for="r in racers" :id="'dot-'+r.key"><circle r="15" :fill="r.color" stroke="#fff" stroke-width="3"/><text class="dot-name" x="22" y="5">@{{ r.name }}</text></g></svg></div><aside class="leaderboard"><h2>Placar ao vivo</h2><div v-for="(r,i) in liveOrder" class="leader"><span class="rank">@{{ i+1 }}º</span><span class="swatch" :style="{background:r.color}"></span><strong>@{{ r.name }}</strong></div><p v-if="liveOrder.length">🔥 Na frente: <strong>@{{ liveOrder[0].name }}</strong> · 🐌 Atrás: <strong>@{{ liveOrder[liveOrder.length-1].name }}</strong></p></aside><div v-if="finished" class="result"><h2>🏆 @{{ winner }}</h2><strong>Campeão da corrida!</strong><ol><li v-for="r in race.results">@{{ r.position }}º — @{{ r.name }}</li></ol><button @click="raceScreen=false">Voltar ao painel</button></div></div><div v-if="showQr" class="fullscreen" style="background:#fffaf0;color:#10283d;display:grid;place-items:center"><div class="qr"><div><small>ESCANEIE PARA PARTICIPAR</small><h1>Pato na Pista</h1></div><div id="qrcodeFull"></div><button @click="showQr=false">Fechar</button></div></div></main><script>const{createApp}=Vue;createApp({data(){return{race:@json($race??null),newName:'',joinUrl:'',raceScreen:false,finished:false,showQr:false,duration:60,remaining:60,racers:[],liveOrder:[],winner:'',poll:null,timer:null,frame:null}},mounted(){this.setup()},methods:{setup(){this.joinUrl=location.origin+'/join/'+this.race.code;setTimeout(()=>new QRCode(document.getElementById('qrcode'),{text:this.joinUrl,width:230,height:230}),50);this.poll=setInterval(async()=>{if(!this.raceScreen){const r=await fetch('/api/races/'+this.race.code);if(r.ok)this.race=await r.json()}},1000)},async addName(){const name=this.newName.trim();if(!name)return;const r=await fetch('/api/races/'+this.race.code+'/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,session:'organizer-'+crypto.randomUUID()})});if(r.ok){this.race=await r.json();this.newName=''}else alert((await r.json()).message||'Não foi possível cadastrar')},async removeName(name){this.race.names=this.race.names.filter(n=>n!==name);await fetch('/api/races/'+this.race.code+'/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({names:this.race.names})})},openQr(){this.showQr=true;setTimeout(()=>new QRCode(document.getElementById('qrcodeFull'),{text:this.joinUrl,width:520,height:520}),50)},startRace(){if(this.race.names.length<2){alert('Cadastre pelo menos 2 participantes.');return}this.raceScreen=true;this.finished=false;this.remaining=this.duration;const colors=['#ff5f56','#ffd60a','#30d158','#64d2ff','#bf5af2','#ff9f0a','#ff375f','#5e5ce6'];this.racers=this.race.names.map((name,i)=>({name,key:i,color:colors[i%colors.length],progress:0,speeds:Array.from({length:8},()=>.65+Math.random()*1.1)}));this.liveOrder=[...this.racers];this.$nextTick(async()=>{const path=document.getElementById('racePath'),length=path.getTotalLength(),started=performance.now();const tick=now=>{const elapsed=Math.min(this.duration*1000,now-started);this.racers.forEach((r,i)=>{const cycle=Math.min(1,elapsed/(this.duration*1000));const segment=Math.min(7,Math.floor(cycle*8));const local=cycle*8-segment;const weights=r.speeds,total=r.speeds.reduce((a,b)=>a+b,0);let before=weights.slice(0,segment).reduce((a,b)=>a+b,0)/total;r.progress=Math.min(1,before+(local*weights[segment])/total);const p=path.getPointAtLength(r.progress*length),el=document.getElementById('dot-'+r.key);if(el)el.setAttribute('transform',`translate(${p.x} ${p.y})`)});this.liveOrder=[...this.racers].sort((a,b)=>b.progress-a.progress);if(elapsed<this.duration*1000)this.frame=requestAnimationFrame(tick)};this.frame=requestAnimationFrame(tick)});this.timer=setInterval(()=>{this.remaining--;if(this.remaining<=0)clearInterval(this.timer)},1000);fetch('/api/races/'+this.race.code+'/start',{method:'POST'}).then(r=>r.json()).then(next=>setTimeout(()=>{this.race=next;this.winner=next.results[0].name;this.finished=true;clearInterval(this.timer)},this.duration*1000))},exportCsv(){const a=document.createElement('a');a.href='data:text/csv,nome,posicao%0A'+(this.race.results||[]).map(r=>r.name+','+r.position).join('%0A');a.download='resultado.csv';a.click()}}}).mount('#app')</script></body></html>
